    'euro_final_v2' => 'Es ist das :competition_de-Finale gegen :opponent_el. Ruhm oder Enttäuschung: In einer solchen Nacht gibt es kein Zwischending. Die Kabine träumt die ganze Saison von diesem Moment.',
    'euro_semi_home_v1_headline' => ':competition_de-Halbfinale zu Hause gegen :opponent_el',
    'euro_semi_home_v1' => ':competition_de-Halbfinale in eurem Stadion gegen :opponent_el. Einen Schritt vom kontinentalen Finale entfernt, mit der Tribüne voll dahinter. Die Atmosphäre wird die großer Europapokal-Nächte sein.',
    'euro_semi_home_v2_headline' => 'Unter den besten Vier :competition_de',
    'euro_semi_home_v2' => 'Unter den besten Vier :competition_de: Ihr empfangt :opponent_a, das Finale steht auf dem Spiel. Die Auslosung wollte, dass es zu Hause entschieden wird, und das muss man nutzen.',
    'euro_semi_away_v1_headline' => ':competition_de-Halbfinale auswärts',
    'euro_semi_away_v1' => ':competition_de-Halbfinale auswärts gegen :opponent_el. Einen Schritt vom Finale entfernt, mit allem gegen sich außer dem Glauben: Das sind die Nächte, die große Teams definieren.',
    'euro_semi_away_v2_headline' => 'Einen Schritt vom :competition_de-Finale entfernt',
    'euro_semi_away_v2' => 'Unter den besten Vier :competition_de: Ihr reist zu :opponent_a, das Finale steht auf dem Spiel. Ein positives Ergebnis auswärts würde die Runde weitgehend in die richtige Bahn lenken.',
    'euro_knockout_home_v1_headline' => 'Europäische Nacht: Siegen oder fallen gegen :opponent_el',
    'euro_knockout_home_v1' => ':competition_de-K.-o.-Duell in eurem Stadion. Ihr empfangt :opponent_a: Siegen oder fallen. Kontinentale Nächte haben etwas Besonderes, und die Tribüne weiß es.',
    'euro_knockout_home_v2_headline' => 'Duell auf Leben und Tod gegen :opponent_el',
    'euro_knockout_home_v2' => 'Europäisches Duell auf Leben und Tod gegen :opponent_el zu Hause. Kein Spielraum für Fehler: Ein schlechter Tag, und man ist raus aus Europa. Die Konzentration muss total sein.',
    'euro_knockout_away_v1_headline' => 'Kontinentale Prüfung auswärts',
    'euro_knockout_away_v1' => ':competition_de-K.-o.-Duell auswärts. Ihr reist zu :opponent_a: Siegen oder fallen. Ein gutes Ergebnis in der Fremde ist der halbe Einzug: Das Team reist mit Ambition.',
    'euro_knockout_away_v2_headline' => 'Kein Spielraum für Fehler bei :opponent_de',
    'euro_knockout_away_v2' => 'Europäisches Duell auf Leben und Tod bei :opponent_de. Kein Spielraum für Fehler. Die Gegnerin ist zu Hause furchteinflößend, aber dieses Team hat schon bewiesen, dass es auswärts nicht einknickt.',
    'euro_group_home_v1_headline' => ':competition_de-Nacht unter Flutlicht',
    'euro_group_home_v1' => ':competition_de-Nacht unter Flutlicht. Ihr empfangt :opponent_a, der Kontinent steht auf dem Spiel, und es müssen Punkte her, um die Qualifikation nicht zu verkomplizieren. Die Hymne wird erklingen, und die Haut wird kribbeln.',
    'euro_group_home_v2_headline' => ':competition_el kehrt in euer Stadion zurück',
    'euro_group_home_v2' => ':competition_el kehrt in euer Stadion zurück: Ihr empfangt :opponent_a. Die Heimpunkte sind nicht verhandelbar, wenn man weiterkommen will.',
    'euro_group_away_v1_headline' => 'Europäische Reise gegen :opponent_el',
    'euro_group_away_v1' => ':competition_de-Nacht auswärts. Ihr reist zu :opponent_a unter Flutlicht, in ein Stadion, das laut ist. Auswärts zu punkten, ist in der Gruppenphase immer Gold wert.',
    'euro_group_away_v2_headline' => 'Kontinentales Duell in der Fremde',
    'euro_group_away_v2' => 'Europäisches Duell in der Fremde gegen :opponent_el in :competition_el. Die Reise ist lang und die Gegnerin anspruchsvoll: Es braucht die beste Version des Teams.',

    // ── Rivalität und Duelle ────────────────────────────────────────

    'rivalry_won_reverse_v1_headline' => 'Ihr habt :opponent_a :score geschlagen: Wiederholen',
    'rivalry_won_reverse_v1' => 'Ihr habt :opponent_a im Hinspiel :score geschlagen. Wiederholen: Die Gegnerin wird auf Revanche sinnen und mit dem Messer zwischen den Zähnen herauskommen. Keine Überheblichkeit.',
    'rivalry_won_reverse_v2_headline' => 'Das letzte Duell ging an euch',
    'rivalry_won_reverse_v2' => 'Das letzte Duell ging an euch (:score gegen :opponent_el). Hohe Moral, aber Präzedenzfälle spielen nicht mit: Jedes Spiel beginnt bei null.',
    'rivalry_lost_reverse_v1_headline' => 'Zeit für die Revanche gegen :opponent_el',
    'rivalry_lost_reverse_v1' => ':Opponent_el hat das Hinspiel :score gewonnen. Zeit für die Revanche: Die Kabine hat jene Niederlage noch im Nacken, und die Tribüne auch. Emotionale Derbys gewinnt man mit kühlem Kopf.',
    'rivalry_lost_reverse_v2_headline' => 'Offene Rechnung mit :opponent_el',
    'rivalry_lost_reverse_v2' => 'Es gibt eine offene Rechnung: :opponent_el hat die Punkte :score das letzte Mal mitgenommen. Das Trainerteam hat jenes Spiel bis zum Überdruss analysiert: Dieselben Fehler werden sich nicht wiederholen.',
    'rivalry_drew_reverse_v1_headline' => 'Die Waage gegen :opponent_el kippen',
    'rivalry_drew_reverse_v1' => 'Unentschieden gegen :opponent_el im Hinspiel. Die Chance, die Waage in einem Duell zu kippen, das historisch durch Details entschieden wird. Die Ambition muss den Respekt überwiegen.',
    'rivalry_drew_reverse_v2_headline' => 'Brich die Gleichheit gegen :opponent_el',
    'rivalry_drew_reverse_v2' => 'Das Hinspiel-Duell mit :opponent_el endete unentschieden — brich die Gleichheit. Es sind zwei Teams auf Augenhöhe, und das Spiel wird in den Strafräumen entschieden.',

    // ── Transfermarkt ───────────────────────────────────────────────

    'market_courted_v1_headline' => ':Club_el macht ernst bei :player',
    'market_courted_v1' => ':Club_el hat bei :player ernst gemacht. Achtung in der Kabine: Solche Gerüchte lenken ab, und die Spielerin muss Professionalität beweisen. Der Klub verweist vorerst auf die Klausel.',
    'market_courted_v2_headline' => 'Spekulationen um :player nehmen zu',
    'market_courted_v2' => 'Die Spekulationen um :player nehmen zu, mit dem Interesse :club_de. Ihr Berater dementiert nichts, was die Gerüchte nährt. Die Fans drücken die Daumen.',
    'market_courted_v3_headline' => 'Gerüchte: :player auf der Liste :club_de',
    'market_courted_v3' => 'Gerüchte bringen :player mit :club_el in Verbindung. Vorerst liegt kein formelles Angebot auf dem Tisch, aber wo Rauch ist... Der Markt heizt sich auf.',
    'market_precontract_v1_headline' => ':Club_el umwirbt :player für einen Vorvertrag',
    'market_precontract_v1' => ':Club_el umwirbt :player für einen Vorvertrag. Ihre Zukunft steht in den Sternen, und der Klub riskiert, sie ablösefrei zu verlieren. Die Verlängerung sollte Priorität haben.',
    'market_precontract_v2_headline' => ':Club_el fühlt bei :player vor: Unruhe',
    'market_precontract_v2' => ':Club_el fühlt bei :player vor — Nachrichten, die beunruhigen. Ohne baldige Verlängerung kann die Spielerin frei verhandeln. Die sportliche Leitung hat Arbeit.',
    'market_precontract_v3_headline' => 'Vorvertrag am Horizont für :player',
    'market_precontract_v3' => ':Club_el würde ein Vorvertragsangebot für :player vorbereiten. Die Uhr tickt gegen den Klub: Jede Woche ohne Verlängerung senkt den Preis eines möglichen Transfers.',
    'market_multiple_targets_v1_headline' => 'Geier lauern: :count Spielerinnen im Schaufenster',
    'market_multiple_targets_v1' => 'Geier lauern: :count eurer Spielerinnen wecken Interesse auf dem Markt. So viele gefragte Fußballerinnen zu haben, ist ein gutes Zeichen, aber sie zu halten, wird die große Schlacht des Sommers.',
    'market_multiple_targets_v2_headline' => ':count Fußballerinnen mit Verehrern',
    'market_multiple_targets_v2' => ':count Fußballerinnen haben Verehrer. Der Markt stellt eure Nerven auf die Probe: Gut zu verkaufen, ist auch gut einzukaufen — aber die Fans würden einen Ausverkauf nicht verzeihen.',
    'market_window_closing_v1_headline' => 'Der Markt schließt: Letzte Stunden',
    'market_window_closing_v1' => 'Der Markt steht kurz vor dem Schließen — letzte Chance zu handeln. Die Telefone in den Büros glühen, und Last-Minute-Bewegungen werden erwartet. Niemand darf einschlafen.',
    'market_window_closing_v2_headline' => 'Marktschließung um die Ecke',
    'market_window_closing_v2' => 'Die Schließung lauert. Der Markt schließt in wenigen Spieltagen, und es liegen noch offene Akten auf dem Tisch. Die sportliche Leitung eilt mit den letzten Schritten.',

    // ── Turnier: Gruppenphase ───────────────────────────────────────

    'wc_group_opener_v1_headline' => 'WM-Auftakt: Gut starten',
    'wc_group_opener_v1' => 'Eröffnungsspiel der Weltmeisterschaft. Eine gute Gelegenheit, gut zu starten und den Rest der Gruppe unter Druck zu setzen. Debüts bringen immer Nerven mit: Wer sie besser managt, trifft zuerst.',
    'wc_group_opener_v2_headline' => 'Das Turnier beginnt: Drei goldene Punkte',
    'wc_group_opener_v2' => 'Erstes Spiel des Turniers. Drei Punkte hier wären ein großartiger Start und würden das Bild der Gruppe völlig verändern. Die Vorbereitung war lang: Es ist Zeit, es zu beweisen.',
    'wc_group_opener_v3_headline' => 'DER VORHANG HEBT SICH',
    'wc_group_opener_v3' => 'Das WM-Abenteuer beginnt. Die Kabine träumt seit Monaten von diesem Moment, und das ganze Land hält den Atem an. Möge die Show beginnen.',
    'wc_group_must_win_v1_headline' => 'Nur ein Sieg zählt',
    'wc_group_must_win_v1' => 'Letztes Gruppenspiel. Nur ein Sieg zählt: Die Rechnung ist klar, und es gibt keinen Plan B. Das Team muss von Beginn an riskieren, auch auf Kosten von Räumen in der Defensive.',
    'wc_group_must_win_v2_headline' => 'Pflichtsieg, um am Leben zu bleiben',
    'wc_group_must_win_v2' => 'Pflichtsieg, um die Qualifikationschancen zu wahren. Der Druck ist maximal, aber genau solche Spiele formen große Nationalteams.',
    'wc_group_must_win_v3_headline' => 'VORGEZOGENES FINALE',
    'wc_group_must_win_v3' => 'Ohne Sieg geht es mit den Koffern zum Flughafen. Die Kabine weiß es, und die Fans auch: Heute hilft kein Spekulieren. Alles geben ab Minute eins.',
    'wc_group_top_v1_headline' => 'Spitzenreiterinnen der Gruppe :group',
    'wc_group_top_v1' => 'Spitzenreiterinnen der Gruppe :group. Die Qualifikation hängt von euch ab: Ein Sieg heute würde den Einzug als Gruppenerste fast besiegeln. Der Bundestrainer bittet, nicht nachzulassen.',
    'wc_group_top_v2_headline' => 'An der Spitze der Gruppe :group',
    'wc_group_top_v2' => 'An der Spitze der Gruppe :group vor dem nächsten Spiel. Der Schwung ist positiv, und die Kabine ist geeint. Die Führung zu halten, brächte ein günstigeres Los.',
    'wc_group_top_v3_headline' => 'GIBT IN DER GRUPPE DEN TON AN',
    'wc_group_top_v3' => 'Gesetzte der Gruppe :group. Das Turnier lächelt vorerst: Weiter punkten, um den Gegner im Achtelfinale zu wählen.',
    'wc_group_qualified_v1_headline' => 'Qualifiziert: Jetzt Platz eins holen',
    'wc_group_qualified_v1' => 'Bereits für die K.-o.-Phase qualifiziert. Es geht noch um Platz eins, der die Brocken in der Auslosung vermeidet. Rotationen werden erwartet, aber niemand will die Dynamik verlieren.',
    'wc_group_qualified_v2_headline' => 'Ticket gelöst: Spiel, um Rhythmus zu holen',
    'wc_group_qualified_v2' => 'Qualifikation gesichert. Dieses Spiel dient dazu, Rhythmus zu holen und den weniger Eingesetzten Minuten zu geben. Das Ziel: Mit der ganzen Gruppe heiß ins Achtelfinale gehen.',
    'wc_group_qualified_v3_headline' => 'TICKET GELÖST',
    'wc_group_qualified_v3' => 'Jetzt Platz eins in der Gruppe holen. Die gute Arbeit in den ersten beiden Spieltagen erlaubt es, dieses Spiel ohne Druck anzugehen: Ein Luxus bei einer WM.',
    'wc_group_on_brink_v1_headline' => 'Die Qualifikation zum Greifen nah',
    'wc_group_on_brink_v1' => 'Die Qualifikation ist nah. Ein gutes Ergebnis könnte reichen, und die Kabine rechnet seit Tagen. Besser nicht von Dritten abhängen: Macht es heute fest.',
    'wc_group_on_brink_v2_headline' => 'Ein Punkt könnte reichen',
    'wc_group_on_brink_v2' => 'Nah an der K.-o.-Phase. Ein Punkt heute könnte sie besiegeln, aber auf Unentschieden zu spielen, geht meist schief. Der Plan: Wie immer auf Sieg spielen.',
    'wc_group_on_brink_v3_headline' => 'EINEN SCHRITT ENTFERNT',
    'wc_group_on_brink_v3' => 'Ein Unentschieden könnte für das Weiterkommen reichen. Auf der Tribüne raucht der Taschenrechner, aber auf dem Platz zählt nur eines: kämpfen.',
    'wc_group_eliminated_v1_headline' => 'Letzter Tanz im Turnier',
    'wc_group_eliminated_v1' => 'Die Qualifikation ist nicht mehr möglich. Es bleibt ein letztes Spiel, um mit Würde anzutreten und sich erhobenen Hauptes vom Turnier zu verabschieden. Die Jungen bekommen Minuten.',
    'wc_group_eliminated_v2_headline' => 'Die Gruppenphase mit Ehre beenden',
    'wc_group_eliminated_v2' => 'Raus aus dem Rennen, aber es bleibt ein Spiel, um die Gruppenphase zu beenden. Der Stolz steht auf dem Spiel, und der Bundestrainer will Charakter sehen.',
    'wc_group_eliminated_v3_headline' => 'ENDE DES TRAUMS',
    'wc_group_eliminated_v3' => 'Letzter Tanz in der Gruppenphase. Das Turnier ist nicht wie erhofft gelaufen, aber das Trikot wird bis zum Schluss verteidigt.',
    'wc_group_gd_v1_headline' => 'Die Tordifferenz kann entscheiden',
    'wc_group_gd_v1' => 'Die Tordifferenz könnte entscheidend sein. Sehr ausgeglichene Gruppe, in der jedes Tor doppelt zählt. Der Bundestrainer hat schon gewarnt: Wenn es geht, Tore schießen.',
    'wc_group_gd_v2_headline' => 'Enge Gruppe: Jedes Tor zählt',
    'wc_group_gd_v2' => 'Enge Gruppe. Die Tordifferenz kann die Teams am Ende trennen, also gilt: Auch bei entschiedenem Spiel den Fuß nicht vom Gas nehmen.',
    'wc_group_gd_v3_headline' => 'TASCHENRECHNER IN DER HAND',
    'wc_group_gd_v3' => 'Die Tordifferenz könnte die Gruppe entscheiden. Punktgleichheiten werden über Tore aufgelöst: Jedes Tor kann eine Qualifikation wert sein.',

    // ── Turnier: K.-o.-Phase ────────────────────────────────────────

    'wc_knockout_r32_v1_headline' => 'Sechzehntelfinale: Kein Spielraum für Fehler',
    'wc_knockout_r32_v1' => 'Sechzehntelfinale. Direkte Elimination, kein Spielraum für Fehler: Ein schlechter Tag, und es geht nach Hause. Die Spannung liegt seit der Hymne in der Luft.',
    'wc_knockout_r32_v2_headline' => 'Jetzt wird es ernst: Siegen oder nach Hause',
    'wc_knockout_r32_v2' => 'Die K.-o.-Phase beginnt. Eine Niederlage hier bedeutet das Turnierende, also wird der Ansatz von höchster Vorsicht geprägt sein. Details entscheiden.',
    'wc_knockout_r32_v3_headline' => 'AUF LEBEN UND TOD',
    'wc_knockout_r32_v3' => 'Die direkte Elimination beginnt. Neunzig Minuten — oder einhundertzwanzig — um weiter zu träumen. Es gibt kein Morgen.',
    'wc_knockout_r16_v1_headline' => 'Achtelfinale: Noch 16 dabei',
    'wc_knockout_r16_v1' => 'Achtelfinale. Sechzehn Nationalteams sind noch im Wettbewerb, und das Niveau ist bereits enorm hoch. Hier zu überleben, ist Sache großer Teams.',
    'wc_knockout_r16_v2_headline' => 'Unter den letzten 16 der Welt',
    'wc_knockout_r16_v2' => 'Unter den letzten 16. Das Niveau der Gegnerinnen steigt ab hier, und jeder Aussetzer wird teuer bezahlt. Die Erfahrung in solchen Spielen wird entscheidend sein.',
    'wc_knockout_r16_v3_headline' => 'NOCH 16',
    'wc_knockout_r16_v3' => 'WM-Achtelfinale. Das Turnier wird enger, und nur die Besten überleben.',
    'wc_knockout_qf_v1_headline' => 'Viertelfinale: Drei Spiele vom Titel entfernt',
    'wc_knockout_qf_v1' => 'Ihr habt das Viertelfinale erreicht. Nur drei Spiele trennen euch vom Weltmeistertitel. Die Kabine weiß es, und die Euphorie ist grenzenlos — aber das Schwerste liegt noch vor euch.',
    'wc_knockout_qf_v2_headline' => 'Unter den besten Acht: Im Spiel das Halbfinale',
    'wc_knockout_qf_v2' => 'Unter den besten Acht. Im Spiel ein Platz im Halbfinale, wo schon die Geschichte wartet. Die Gegnerin ist eine, die Angst macht — aber in dieser Phase sind sie das alle.',
    'wc_knockout_qf_v3_headline' => 'ELITE-TERRITORIUM',
    'wc_knockout_qf_v3' => 'Nur noch acht Nationalteams im Turnier. Jedes Spiel ab jetzt ist ein vorgezogenes Finale.',
    'wc_knockout_sf_v1_headline' => 'Halbfinale: Siegen heißt Finale spielen',
    'wc_knockout_sf_v1' => 'Halbfinale. Heute zu gewinnen, bedeutet, das WM-Finale zu spielen. Das Land hält den Atem an, und die Kabine bereitet diesen Moment das ganze Leben vor. Möge die Hand nicht zittern.',
    'wc_knockout_sf_v2_headline' => 'Ein Spiel vom Finale entfernt',
    'wc_knockout_sf_v2' => 'Ein Spiel vom Finale entfernt. Das wichtigste Spiel des Turniers bis jetzt, mit Verlaub vor dem, was danach kommen mag. Das emotionale Management wird entscheidend sein.',
    'wc_knockout_sf_v3_headline' => 'VOR DEN TOREN DES FINALES',
    'wc_knockout_sf_v3' => 'Neunzig Minuten, um Geschichte zu schreiben. Das Finale ist so nah, dass man es fast berühren kann.',
    'wc_knockout_third_v1_headline' => 'Die Bronze steht auf dem Spiel',
    'wc_knockout_third_v1' => 'Spiel um Platz drei. Noch steht eine Medaille auf dem Spiel und der Stolz, das Turnier auf dem Podium zu beenden. Es schmerzt, nicht im Finale zu stehen, aber eine Medaille ist für immer.',
    'wc_knockout_third_v2_headline' => 'Bronze holen, erhobenen Hauptes',
    'wc_knockout_third_v2' => 'Das Spiel um Bronze. Die Chance, ein Turnier, das zu wenig hergab, mit einer positiven Note zu beenden. Der Bundestrainer wird denen Minuten geben, die am wenigsten gespielt haben.',
    'wc_knockout_third_v3_headline' => 'DER TROSTPREIS',
    'wc_knockout_third_v3' => 'Aber eine Medaille ist eine Medaille. Platz drei wird weniger gefeiert, aber immer erinnert.',
    'wc_knockout_final_v1_headline' => 'DAS WM-FINALE',
    'wc_knockout_final_v1' => 'Das WM-Finale. Das letzte Spiel des Turniers, das der ganze Planet sehen wird. Neunzig Minuten für die Unsterblichkeit: Die Namen der Weltmeisterinnen werden für immer erinnert.',
    'wc_knockout_final_v2_headline' => 'Ein Spiel, das den Weltmeister kürt',
    'wc_knockout_final_v2' => 'Das Finale. Ein Spiel, das den Weltmeister kürt. Alles davor — Jahre der Arbeit, der Opfer — führt zu dieser Nacht.',
    'wc_knockout_final_v3_headline' => 'DAS SPIEL',
    'wc_knockout_final_v3' => 'Das Finale der Welt. Keine Worte: Es muss nur noch gespielt werden.',

    // ── Turnier: Gegnerkontext ──────────────────────────────────────

    'wc_opponent_group_leader_v1_headline' => ':opponent, Spitzenreiter der Gruppe: Anspruchsvolle Prüfung',
    'wc_opponent_group_leader_v1' => ':opponent führt die Gruppe an. Ein auf dem Papier anspruchsvolles Spiel gegen die formstärkste Auswahl der Gruppe. Hier zu punkten, wäre doppelt wertvoll.',
    'wc_opponent_group_leader_v2_headline' => 'Der Schrecken der Gruppe: :opponent',
    'wc_opponent_group_leader_v2' => ':opponent ist Gruppenerste. Ein guter Gradmesser, um die wahren Ambitionen im Turnier zu messen.',
    'wc_opponent_group_leader_v3_headline' => 'DER SCHRECKEN DER GRUPPE',
    'wc_opponent_group_leader_v3' => ':opponent gibt in der Tabelle den Ton an. Niemand konnte sie bisher stoppen: Die Ersten zu sein, wäre ein Ausrufezeichen.',
    'wc_opponent_group_bottom_v1_headline' => ':opponent, Schlusslicht: Tückisches Spiel',
    'wc_opponent_group_bottom_v1' => ':opponent ist Gruppenletzte. Trotzdem ist auf diesem Niveau nichts einfach: Sie spielen ohne Druck, und das macht sie gefährlich. Entspannen verboten.',
    'wc_opponent_group_bottom_v2_headline' => 'Außenseiterin der Gruppe, aber mit Stolz',
    'wc_opponent_group_bottom_v2' => ':opponent ist auf dem Papier Gruppenletzte, aber in einem Turnier ist die Form unberechenbar. Sie werden sich mit Würde verabschieden wollen.',
    'wc_opponent_group_bottom_v3_headline' => 'AUSSENSEITERIN DER GRUPPE',
    'wc_opponent_group_bottom_v3' => ':opponent hat nichts zu verlieren. Und Teams, die nichts zu verlieren haben, sind die gefährlichsten.',
    'wc_opponent_tournament_streak_v1_headline' => ':opponent mit weißer Weste',
    'wc_opponent_tournament_streak_v1' => ':opponent hat alle bisherigen Turnierspiele gewonnen. Die formstärkste Auswahl der Meisterschaft: Sie zu stoppen, wäre die Sensation der WM.',
    'wc_opponent_tournament_streak_v2_headline' => ':opponent, ungeschlagen: Extrem komplizierte Gegnerin',
    'wc_opponent_tournament_streak_v2' => ':opponent ist im Wettbewerb ungeschlagen. Eine komplizierte Gegnerin, die in diesem Turnier keine Niederlage kennt. Es braucht das perfekte Spiel.',
    'wc_opponent_tournament_streak_v3_headline' => 'UNAUFHALTSAM',
    'wc_opponent_tournament_streak_v3' => ':opponent kommt mit weißer Weste. Der Favoritinnenstatus gehört ihnen, aber Favoritinnen fallen auch.',
    'wc_opponent_winless_v1_headline' => ':opponent noch ohne Sieg: Angeschlagen und gefährlich',
    'wc_opponent_winless_v1' => ':opponent hat in diesem Turnier noch nicht gewonnen. Sie kommen angeschlagen und mit der Notwendigkeit, ihr Gesicht zu wahren: Genau die Art Gegnerin, die jedem das Leben schwer macht.',
    'wc_opponent_winless_v2_headline' => ':opponent sucht den ersten Sieg',
